 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    overall = Counter(v for row in grid for v in row)
    bg = overall.most_common(1)[0][0]

    def dominant(values):
        color, count = Counter(values).most_common(1)[0]
        return color, count / len(values)

    # Full-width / full-height separator bands are dominated by a color other
    # than the large field color. Adjacent bands collapse to one coordinate.
    row_coords = [r for r in range(h)
                  if dominant(grid[r])[0] != bg and dominant(grid[r])[1] >= 0.55]
    col_coords = [c for c in range(w)
                  if (lambda x: x[0] != bg and x[1] >= 0.55)(dominant([grid[r][c] for r in range(h)]))]

    def collapse(coords):
        groups = []
        for x in coords:
            if groups and x == groups[-1][-1] + 1:
                groups[-1].append(x)
            else:
                groups.append([x])
        return [g[len(g)//2] for g in groups]
    rs, cs = collapse(row_coords), collapse(col_coords)
    if len(rs) < 2 or len(cs) < 2:
        return [[bg]]

    result = []
    for r0, r1 in zip(rs, rs[1:]):
        row = []
        for c0, c1 in zip(cs, cs[1:]):
            # A marker is encoded by the same exceptional color at all four
            # corners of a cell; otherwise the cell keeps its interior fill.
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            corner_color = corners[0]
            vals = [grid[r][c] for r in range(r0+1, r1) for c in range(c0+1, c1)]
            fill = Counter(vals).most_common(1)[0][0] if vals else bg
            row.append(corner_color if len(set(corners)) == 1 and corner_color != bg else fill)
        result.append(row)

    # Remove blank outer lanes that contain no encoded object color.
    while result and all(v == bg for v in result[0]): result.pop(0)
    while result and all(v == bg for v in result[-1]): result.pop()
    if result:
        while result and all(row[0] == bg for row in result):
            for row in result: row.pop(0)
        while result and all(row[-1] == bg for row in result):
            for row in result: row.pop()
    return result
